package view;

import controller.AdminController; import model.*; import javax.swing.*; import javax.swing.table.DefaultTableModel; import java.awt.*;

public class AdminView extends DashboardView {
    private final AdminController controller; private final Runnable logout;
    private JTable studentsTable,teachersTable,staffTable; private DefaultTableModel studentsModel,teachersModel,staffModel;
    public AdminView(AdminController c,String name,Runnable logout){super("Admin",name);this.controller=c;this.logout=logout;buildPages();refreshAll();setVisible(true);}
    protected void onLogout(){logout.run();}
    protected void buildNavigation(JPanel side){addNav(side,"Overview","Dashboard");addNav(side,"Students","Students");addNav(side,"Teachers","Teachers");addNav(side,"Staff","Staff");}
    private void buildPages(){
        JPanel home=page("Overview","Manage the people and records in your school.");JPanel stats=new JPanel(new GridLayout(1,3,14,0));stats.setOpaque(false);stats.add(stat("Students",()->controller.getStudents().size()));stats.add(stat("Teachers",()->controller.getTeachers().size()));stats.add(stat("Staff members",()->controller.getStaff().size()));home.add(stats,BorderLayout.CENTER);addPage("Dashboard",home);
        studentsModel=model("Student ID","Name","Username","Class","Attendance");studentsTable=table(studentsModel);addPage("Students",managementPage("Students","Add, edit or remove student records.",studentsTable,"student"));
        teachersModel=model("Teacher ID","Name","Username","Subject");teachersTable=table(teachersModel);addPage("Teachers",managementPage("Teachers","Manage teacher accounts and subjects.",teachersTable,"teacher"));
        staffModel=model("Staff ID","Name","Username","Department");staffTable=table(staffModel);addPage("Staff",managementPage("Staff","Manage staff accounts and departments.",staffTable,"staff"));
    }
    private JPanel stat(String label,java.util.function.IntSupplier value){JPanel p=cardPanel();p.setLayout(new BoxLayout(p,BoxLayout.Y_AXIS));JLabel l=new JLabel(label);l.setForeground(new Color(105,116,135));JLabel n=new JLabel(""+value.getAsInt());n.setFont(new Font("SansSerif",Font.BOLD,30));n.setForeground(new Color(35,75,135));p.add(l);p.add(Box.createVerticalStrut(10));p.add(n);return p;}
    private DefaultTableModel model(String... cols){return new DefaultTableModel(cols,0){public boolean isCellEditable(int r,int c){return false;}};}
    private JTable table(DefaultTableModel m){JTable t=new JTable(m);t.setRowHeight(29);t.getTableHeader().setFont(new Font("SansSerif",Font.BOLD,12));return t;}
    private JPanel managementPage(String title,String sub,JTable table,String type){JPanel p=page(title,sub);JPanel buttons=new JPanel(new FlowLayout(FlowLayout.LEFT,8,0));buttons.setOpaque(false);JButton add=button("Add new"),edit=button("Edit selected"),del=button("Delete selected"),refresh=button("Refresh");buttons.add(add);buttons.add(edit);buttons.add(del);buttons.add(refresh);JPanel body=cardPanel();body.add(new JScrollPane(table),BorderLayout.CENTER);JPanel center=new JPanel(new BorderLayout(0,14));center.setOpaque(false);center.add(buttons,BorderLayout.NORTH);center.add(body,BorderLayout.CENTER);p.add(center,BorderLayout.CENTER);
        add.addActionListener(e->editDialog(type,null));edit.addActionListener(e->{int row=table.getSelectedRow();if(row<0){error("Select a record first.");return;}int id=Integer.parseInt(table.getValueAt(row,0).toString());Object obj=find(type,id);if(obj!=null)editDialog(type,obj);});del.addActionListener(e->{int row=table.getSelectedRow();if(row<0){error("Select a record first.");return;}int id=Integer.parseInt(table.getValueAt(row,0).toString());if(JOptionPane.showConfirmDialog(this,"Delete this record?","Confirm deletion",JOptionPane.YES_NO_OPTION)==JOptionPane.YES_OPTION){boolean ok=type.equals("student")?controller.deleteStudent(id):type.equals("teacher")?controller.deleteTeacher(id):controller.deleteStaff(id);if(ok)refreshAll();}});refresh.addActionListener(e->refreshAll());return p;}
    private JButton button(String text){JButton b=new JButton(text);b.setFocusPainted(false);return b;}
    private Object find(String type,int id){if(type.equals("student"))for(Student x:controller.getStudents())if(x.getStudentId()==id)return x;if(type.equals("teacher"))for(Teacher x:controller.getTeachers())if(x.getTeacherId()==id)return x;if(type.equals("staff"))for(Staff x:controller.getStaff())if(x.getStaffId()==id)return x;return null;}
    private void editDialog(String type,Object existing){boolean edit=existing!=null;JTextField id=new JTextField(edit?""+ (type.equals("student")?((Student)existing).getStudentId():type.equals("teacher")?((Teacher)existing).getTeacherId():((Staff)existing).getStaffId()):"");JTextField name=new JTextField(edit?((User)existing).getName():"");JTextField username=new JTextField(edit?((User)existing).getUsername():"");JPasswordField password=new JPasswordField(edit?((User)existing).getPassword():"");JTextField extra=new JTextField(edit?(type.equals("student")?((Student)existing).getClassName():type.equals("teacher")?((Teacher)existing).getSubject():((Staff)existing).getDepartment()):"");
        Object[] fields={type.substring(0,1).toUpperCase()+type.substring(1)+" ID",id,"Full name",name,"Username"+(edit?" (read-only; unchanged)":""),username,"Password",password,type.equals("student")?"Class":type.equals("teacher")?"Subject":"Department",extra};if(edit)username.setEditable(false);
        int result=JOptionPane.showConfirmDialog(this,fields,(edit?"Edit ":"Add ")+type,JOptionPane.OK_CANCEL_OPTION,JOptionPane.PLAIN_MESSAGE);if(result!=JOptionPane.OK_OPTION)return;
        try{int key=Integer.parseInt(id.getText().trim());String nm=name.getText().trim(),un=username.getText().trim(),pw=new String(password.getPassword()),ex=extra.getText().trim();if(nm.isEmpty()||pw.isEmpty()||ex.isEmpty()||(!edit&&un.isEmpty())){error("Please complete all fields.");return;}boolean ok;
            if(type.equals("student")){ok=edit?controller.modifyStudent(key,nm,pw,ex):controller.addStudent(new Student(key,un,pw,nm,ex));}
            else if(type.equals("teacher")){ok=edit?controller.modifyTeacher(key,nm,pw,ex):controller.addTeacher(new Teacher(key,un,pw,nm,ex));}
            else{ok=edit?controller.modifyStaff(key,nm,pw,ex):controller.addStaff(new Staff(key,un,pw,nm,ex));}
            if(ok){info(edit?"Record updated successfully.":"Record added successfully.");refreshAll();}else error(edit?"Record not found.":"Username or ID already exists.");
        }catch(NumberFormatException exn){error("ID must be a valid number.");}}
    private void refreshAll(){studentsModel.setRowCount(0);for(Student s:controller.getStudents())studentsModel.addRow(new Object[]{s.getStudentId(),s.getName(),s.getUsername(),s.getClassName(),String.format("%.1f%%",s.getAttendance())});teachersModel.setRowCount(0);for(Teacher t:controller.getTeachers())teachersModel.addRow(new Object[]{t.getTeacherId(),t.getName(),t.getUsername(),t.getSubject()});staffModel.setRowCount(0);for(Staff s:controller.getStaff())staffModel.addRow(new Object[]{s.getStaffId(),s.getName(),s.getUsername(),s.getDepartment()});}
}
